def is_power_of_two(n):
    if n <= 0:
        return False              # zero and negatives are never powers of two
    while n > 1:
        if n % 2 != 0:
            return False            # an odd number bigger than 1 breaks the chain
        n //= 2                      # keep halving as long as it divides evenly
    return True                    # reached exactly 1 by only ever halving cleanly


if __name__ == "__main__":
    n = 16
    print(is_power_of_two(n))

