def is_power_of_two(n):
    if n <= 0:
        return False               # zero and negatives are never powers of two
    lowest_set_bit = n & (-n)      # isolates only the lowest 1-bit of n
    return lowest_set_bit == n     # true only when that lowest bit is the only bit


if __name__ == "__main__":
    n = 16
    print(is_power_of_two(n))

